    function add_to_attr_map(prop)
    {
        // attr_map[prop["v"]] = ""
        attr_map[prop["v"]] = prop["vt"]
    }

    function add_rule(node){
        var type = node.type
        var statement = newline + "\t" + type + " " + node["name"] + ": \n"
        typeql_schema_dict[type] += statement

        // adding definition
        let definition = node["def"]
        let tabs = "\t\t"
        definition = definition.split("\n")
        $.each( definition, (key, value) =>{
            tabs ="\t\t"
            definition[key] = tabs.concat(definition[key])
            definition[key]+= "\n"
            typeql_schema_dict[type] += definition[key]

        })

        // // add corresponding properties
        // node.props.forEach( (prop) =>{
        //     if (prop.p =="when"){
        //         statement = "\t\t" +  prop["p"] + " {\n\t\t\t" + prop["v"] +";\n\t\t }"  
        //         typeql_schema_dict[type] += statement   
        //     }
        //     else{
        //         statement = prop["p"] + " {\n\t\t\t" + prop["v"] + ";\n\t\t }"  
        //         typeql_schema_dict[type] += statement     
        //     }
        //     if (prop["p"] == "owns"){
        //         add_to_map(prop)
        //     }
        // })
        //  add semi colon
        typeql_schema_dict[type] += ";"
    }

    function add_node(node, index, array){
        var type = node.type
        if(type !== "tab"){
            if(type === "submodel"){
                if(typeof submodel_map[node.id] === "undefined"){
                    // console.log(type, " ", node)
                    submodel_map = {...submodel_map, [node.id]: {paths: true, events: false, instances: false}}
                    if(previous_model === ""){
                        added_submodel = {...added_submodel, [node.id]: false}
                        previous_model = node.id
                    }
                    if(previous_model !== node.id){
                        added_submodel = {...added_submodel, [previous_model]: true}
                        added_submodel = {...added_submodel, [node.id]: false}
                        previous_model = node.id
                    }
                    add_causal_paths(node.id)
                }
            }
            if(type === "event"){
                // add event
                if(events_added[node.name] === undefined){
                    events_added = {...events_added, [node.name]: true}
                    var insert_statement = "insert\n$"+ (node.id).split(".").join("") + " isa event, has name \"" + node.name+"\""
                    if(node.output){
                            insert_statement += "\n$"+ (node.id).split(".").join("") + "has output "+ node.output
                    }
                    insert_statement +=";\n\n"
                    typeql_schema_dict["events"] += insert_statement
                }

                // console.log("Event: ", node)

                // add ACTORS to an event
                if(geminos){
                    if(node.props){
                        let entity = ""
                        // console.log(node.props)
                        $.each(node.props , (key, value)=>{

                            if(node.props[key].p==="actor"){
                                statement = "match\n"
                                statement += "$"+ (node.id).split(".").join("") + " isa event, has name \"" + node.name+"\";\n"
                                //v => id of node in  node-red ; vt => knowledge model (flow) id in node-red
                                entity = RED.nodes.node(value.v)
                                statement += "$"+ (entity.id).split(".").join("") + " isa actor_entity, has name \"" + entity.name+"\";\n"
                                statement += "insert\n";
                                statement += "$actors (act: $"+ (node.id).split(".").join("") + ", actor: $"+ (entity.id).split(".").join("")  + ") isa actors_list;\n\n";
                                typeql_schema_dict["actors"] += statement
                            }
                            // let insert_actor = actors[value.v] ? false : true;
                            // console.log(insert_actor)
                            // if(insert_actor){
                            //     // insert new actor into database
                            //     actors = { ...actors,[value.v]:value.vt}
                            //     console.log(actors)
                            // }else{
                            //     // add line to 

                            // }
                            // match 
                            // $event isa event, has id [node.id]
                            // $actor isa actor, has id [actor.id]
                            // insert $actors_list( actor: $actor, act: ) isa actors_list
                        })
                    }
                }

                // add event to a specific causal model
                parent_model= RED.nodes.submodel(node.z) ? RED.nodes.submodel(node.z) : RED.nodes.workspace(node.z) 
                submodel_event = "$"+ (node.id).split(".").join("") + " isa event, has name \""+node.name + "\";\n";
                model_name= parent_model.name ? parent_model.name : parent_model.label
                causal_model = "$causal_model isa causal_model, has name \""+model_name +"\";\n";
                causal_event = "$causal_model(event: $"+ (node.id).split(".").join("") + ");\n"  

                if(submodel_map[node.z] && !added_submodel[node.z]){
                    // console.log("node is in a causal model ", node)
                    // console.log(submodel_map[node.z])
                    if (submodel_map[node.z].events === true)
                    {
                        insert_statement = "match\n"+ submodel_event + causal_model + "insert\n"+ causal_event
                    }
                    else{
                        insert_statement = "match\n"+ submodel_event + "insert\n" + causal_model + causal_event
                        let copy  = {... submodel_map[node.z], events: true}
                        submodel_map = {...submodel_map, [node.z] : copy}

                    }
                    insert_statement += "\n"
                    typeql_schema_dict ["submodel_events"] += insert_statement
                }
            }
            if( /^submodel:(.+)$/.exec(node.type)){
                // console.log(type, " " , node)
                // console.log(/^submodel:(.+)$/.exec(node.type)[1])
                // console.log(submodel_map[/^submodel:(.+)$/.exec(node.type)[1]])

                //get the parent id
                let parent_id = /^submodel:(.+)$/.exec(node.type)[1]

                // check if the parent has been added as an event 
                if(submodel_map[parent_id].instances === false){
                    insert_statement = "insert\n$"+(node.id).split(".").join("")+" isa event, has name \"" + node.name +"\";\n\n"
                    typeql_schema_dict ["events"] += insert_statement 
                    let copy = { ...submodel_map[parent_id], instances: true}
                    submodel_map = { ...submodel_map, [parent_id]:copy}
                }

                // the implementation details of the submodel
                let impl =  RED.nodes.submodel(parent_id)
                instance = "$" + (impl.id).split(".").join("") + " isa causal_model, has name \"" + impl.name + "\";\n";

                // parent_model is where they exist in a flow
                parent_model = RED.nodes.submodel(node.z) ? RED.nodes.submodel(node.z) : RED.nodes.workspace(node.z)               
                model_name = parent_model.name ? parent_model.name : parent_model.label

                causal_model = "$causal_model isa causal_model, has name \""+ model_name + "\";\n";
                causal_instance_list = "$causal_model(submodel: $"+ (impl.id).split(".").join("")+");\n";

                insert_statement = "match\n" + instance + causal_model + "insert\n" + causal_instance_list +"\n";
                typeql_schema_dict ["submodel_submodels"] += insert_statement 
            }
            // =================================================================
            // if(type == "group"){
            //     // grab class type of group to see if it is entity / relationship
            //     type = node["classtype"];
            
            //     nodename = node.name
            //     for (var i = 0; i < node.nodes.length; i++){
            //         n = node.nodes[i]
            //         group_map[n]= nodename
            //     }
            // }
            // else{
            //     // check if node id exists inside a group and update the subtype
            //     if(group_map[node.id])
            //     {
            //         sub = true;
            //         subtype = group_map[node.id]
            //     }
            // }
            // =================================================================
            if(type =="rule"){
                if(!geminos){
                    add_rule(node)
                }
            }
            if(type === "entity" || type === "relation"){
                if(geminos){
                    var parent_type= subtype_map[node.id] ? subtype_map[node.id] : type

                    // [GEMINOS SCHEMA] ENTITY
                    if(type === "entity"){
                        // [GEMINOS SCHEMA] INSERT ENTITY
                        var statement = "\n\ninsert\n$"+(node.id).split(".").join("") +" isa actor_entity,\n"
                        statement = statement + "has name \""+node.name + "\", has id \"" + node.id + "\""
                        statement += ";"
                        typeql_schema_dict[type] += statement

                        // [GEMINOS SCHEMA] INSERT ENTITY INTO KNOWLEDGE MODEL
                        if(kg_[node.z] === true){
                            // console.log("KG already detected ", node)
                            statement = "\match\n$"+ (node.id).split(".").join("") +" isa actor_entity, has id \""+node.id+"\";\n"
                            statement = statement + "$"+(node.z).split(".").join("") +" isa knowledge_model, has id \""+node.z+"\";\n"
                            statement = statement + "insert\n"
                            statement = statement +"$"+(node.z).split(".").join("") +" (kg_entity: $"+(node.id).split(".").join("") +");\n\n"
                            typeql_schema_dict["kg_entity"] += statement
                            // console.log(statement)
                        }else{
                            // console.log("New KG detected ", node)
                            kg_ = {...kg_, [node.z]: true}
                            parent = RED.nodes.subflow(node.z) ? RED.nodes.subflow(node.z) : RED.nodes.workspace(node.z)
                            model_name = parent.name ? parent.name : parent.label
                            statement = "\match\n$"+ (node.id).split(".").join("") +" isa actor_entity, has id \""+node.id+"\";\n"
                            statement = statement + "insert\n"
                            statement = statement + "$"+(node.z).split(".").join("") +" isa knowledge_model, has name \""+model_name+"\", has id \""+node.z+"\";\n"
                            statement = statement +"$"+(node.z).split(".").join("") +" (kg_entity: $"+(node.id).split(".").join("") +");\n\n"
                            typeql_schema_dict["kg_entity"] += statement
                            // console.log(statement)
                        }
                    }

                }else{
                    var statement = newline + "\t" + node["name"] + " sub "
                    typeql_schema_dict[type] += statement
                    
                    // check if node has a parent
                    var parent_type= subtype_map[node.id] ? subtype_map[node.id] : type
                    if(type === "relation"){
                        typeql_schema_dict[type] += parent_type
                    }else{
                        if (parent_type === "entity"){
                            typeql_schema_dict[type]+= parent_type
                        }else{
                            typeql_schema_dict[type]+= parent_type
                        }
                    }
                    typeql_schema_dict[type] += ","

                    // add abstract
                    if(node["abstract"]){
                        typeql_schema_dict[type] += "\n\t\tabstract,"
                    }
                    // add key to class
                    if(typeof node.key !== typeof undefined ){
                        var prop = {
                            v:node.key,
                            vt: node.keytype
                        };
                        add_to_map(prop);
                        var statement = "\n\t\towns " + node.key + " @key,";
                        typeql_schema_dict[type] += statement;
                    };
                    // add corresponding properties
                    if(node.props) {
                    node.props.forEach( (prop) =>{
                        var statement = newline + "\t\t" + prop["p"] + " ";
                        if (prop["p"] == "plays"){
                            // split at ":"
                            if(prop["v"].includes("|")){
                                plays = prop["v"].split(":");
                                roles = plays[1].split("|")
                            
                                for (role in roles){
                                    statement = newline + "\t\t" + prop["p"] + " ";
                                    // console.log(roles[role].replace(" ", ""));
                                    statement = statement + plays[0] + ":" + roles[role].replace(" ", "") + ","
                                    typeql_schema_dict[type] += statement;
                                }
                            }else{
                                plays = prop["v"].split(":");
                                statement = statement + plays[0] + ":" + plays[1] + ","
                                typeql_schema_dict[type] += statement;
                            }
                        }else{
                            statement += prop["v"] + ",";
                            typeql_schema_dict[type] += statement;
                            if (prop["p"] == "owns"){
                                add_to_attr_map(prop);
                            }
                        }
                    });
                    // remove last comma added in props
                    typeql_schema_dict[type] = typeql_schema_dict[type].slice(0,-1);
                    //  add semi colon
                    typeql_schema_dict[type] += ";"
                    }
                }
            }
            // if (type === "attribute"){
            //     var statement = newline + "\t" + node.name + " sub attribute,"
            //     if(node["abstract"]){
            //         statement = statement + newline + "\t\t abstract,"
            //     }
            //     if(attr_map[node.name]){
            //         statement = statement + newline + "\t\t value " + attr_map[node.name] + ";"
            //     }else{
            //         statement = statement + newline + "\t\t value " + node["type"] + ";"
            //     }
            //     typeql_schema_dict[type] += statement
            // }
        }else{
            if(typeof submodel_map[node.id] === "undefined"){
                // console.log(type, " ", node)
                submodel_map = {...submodel_map, [node.id]: {paths: true, events: false, instances: false}}
                if(previous_model === ""){
                    added_submodel = {...added_submodel, [node.id]: false}
                    previous_model = node.id
                }
                if(previous_model !== node.id){
                    added_submodel = {...added_submodel, [previous_model]: true}
                    added_submodel = {...added_submodel, [node.id]: false}
                    previous_model = node.id
                }
            }
        }
    }
    function add_causal_paths(nodeId){
        // get all active links of submodels and main model
        activeLinks = RED.nodes.filterLinks({
            source:{z:nodeId},
            target:{z:nodeId}
        });
        console.log("in add causal_paths for node id ", nodeId)

        activeLinks.forEach( (link)=>{
            // event to event && event to submodel
            // submodel to submodel && submodel to event

            if( link.source.type === "event" || link.source.type.substring(0,9) === "submodel:"){            
                if(link.target.type === "event" || link.target.type.substring(0,9) === "submodel:" ){
                    let cause_id = ""
                    let effect_id = ""
                

                    // cause based on type
                    if( link.source.type === "event"){
                        cause ="$"+(link.source.id).split(".").join("") + " isa event, has name \"" + link.source.name + "\";\n";
                        cause_id = link.source.id
                    }
                    if(link.source.type.substring(0,9) === "submodel:"){
                        let parent_id = /^submodel:(.+)$/.exec(link.source.type)[1]
                        let parent = RED.nodes.submodel(parent_id)
                        cause ="$"+(parent_id).split(".").join("") + " isa causal_model, has name \"" + parent.name + "\";\n";
                        cause_id = parent_id

                    }

                    // effect based on type
                    if( link.target.type === "event"){
                        effect = "$"+(link.target.id).split(".").join("") + " isa event, has name \"" + link.target.name + "\";\n";
                        effect_id = link.target.id
                    }
                    if(link.target.type.substring(0,9) === "submodel:"){
                        let parent_id = /^submodel:(.+)$/.exec(link.target.type)[1]
                        let parent = RED.nodes.submodel(parent_id)
                        effect ="$"+(parent_id).split(".").join("") + " isa causal_model, has name \"" + parent.name + "\";\n";
                        effect_id = parent_id
                    }

                    
                    path = "$causal_path (cause: $"+(cause_id).split(".").join("") +", effect: $"+(effect_id).split(".").join("")+") isa causal_path;\n";

                    insert_statement=
                    "match\n"+ cause + effect + "insert\n"+ path+"\n";
                    typeql_schema_dict["paths"] += insert_statement
                    
                    // ADD PATH TO CURRENT CAUSAL MODEL
                    parent = RED.nodes.submodel(link.source.z) ? RED.nodes.submodel(link.source.z) : RED.nodes.workspace(link.source.z)
                    model_name = parent.name ? parent.name : parent.label
                    causal_model = "$causal_model isa causal_model, has name \"" + model_name + "\";\n";
                    causal_path_list = "$causal_model (causal_path: $causal_path);\n"
                    path = path.replace("cause:", "")
                    path = path.replace("effect:", "")
                    insert_statement =  "match\n"+cause + effect + path + causal_model + "insert\n"+causal_path_list+"\n"

                    typeql_schema_dict["submodel_paths"] += insert_statement
                    
                }
            }

            if(link.source.type === "entity"){
                if(link.target.type === "relation"){
                    subject_id = (link.source.id).split(".").join("");
                    object_id = (link.target.id).split(".").join("");

                    statement = "match\n"
                    statement = statement + "$" + subject_id + " isa actor_entity, has id \"" + link.source.id + "\";\n";
                    let actor_rel = "$" + object_id + " isa actor_relation, has id \""+ link.target.id + "\"";

                    if(kg_relation[link.target.id] === undefined){
                        statement = statement + "insert\n" + actor_rel + ", has name \"" + link.target.name + "\";\n";
                        kg_relation = {...kg_relation, [link.target.id]: true}
                    }else{
                        statement = statement + actor_rel +";\ninsert\n"; 
                    }
                    statement = statement + "$" + object_id + " (actor:$"+subject_id+");\n\n";
                    typeql_schema_dict["relation"] += statement;
                    // [GEMINOS SCHEMA] INSERT RELATION INTO KNOWLEDGE MODEL
                    if(kg_[nodeId] === true){
                        // console.log("KG already detected ", node)
                        statement = "\match\n$"+ object_id +" isa actor_relation, has id \""+ link.target.id+"\";\n"
                        statement = statement + "$"+(nodeId).split(".").join("") +" isa knowledge_model, has id \""+nodeId+"\";\n"
                        statement = statement + "insert\n"
                        statement = statement +"$"+(nodeId).split(".").join("") +" (kg_relation: $"+object_id +");\n\n"
                        typeql_schema_dict["kg_relation"] += statement
                        console.log(statement)
                    }else{
                         // console.log("New KG detected ", node)
                         kg_ = {...kg_, [nodeId]: true}
                        parent = RED.nodes.subflow(nodeId) ? RED.nodes.subflow(nodeId) : RED.nodes.workspace(nodeId)
                        model_name = parent.name ? parent.name : parent.label
                        statement = "\match\n$"+ object_id +" isa actor_relation, has id \""+link.target.id+"\";\n"
                        statement = statement + "insert\n"
                        statement = statement + "$"+(nodeId).split(".").join("") +" isa knowledge_model, has name \""+model_name+"\", has id \""+nodeId+"\";\n"
                        statement = statement +"$"+(nodeId).split(".").join("") +" (kg_relation: $"+object_id +");\n\n"
                        typeql_schema_dict["kg_relation"] += statement
                        console.log(statement)
                    }
                    
                }
            }
        })
    }
    function add_attribute(attr_name, abstract){
        var statement = newline + "\t" + attr_name + " sub attribute," + newline + "\t\t value " + attr_map[attr_name] + ";"
        typeql_schema_dict["attribute"] += statement
    }
